const isFilled = computed(() => !!FILLED[props.name])
const viewBox = computed(() => (isFilled.value ? FILLED[props.name].viewBox : '0 0 24 24'))
const inner = computed(() =>
  isFilled.value
    ? FILLED[props.name].paths.map((d) => `<path d="${d}"/>`).join('')
    : ICONS[props.name] || ''
)
</script>

